import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"常见问题（FAQ）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/FAQ.md","filePath":"guide/FAQ.md"}`),a={name:`guide/FAQ.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="常见问题-faq" tabindex="-1">常见问题（FAQ） <a class="header-anchor" href="#常见问题-faq" aria-label="Permalink to “常见问题（FAQ）”">​</a></h1><p>这里汇总新手最常遇到的问题。如果没找到答案，可以到<a href="./../reference/">参考</a>区按主题查阅，或到<a href="./../contribute/">参与编写文档</a>了解如何提问。</p><h2 id="起步" tabindex="-1">起步 <a class="header-anchor" href="#起步" aria-label="Permalink to “起步”">​</a></h2><h3 id="q-emuera-在哪里下载" tabindex="-1">Q：Emuera 在哪里下载？ <a class="header-anchor" href="#q-emuera-在哪里下载" aria-label="Permalink to “Q：Emuera 在哪里下载？”">​</a></h3><p>A：Emuera 的官方发布页在 OSDN（见<a href="./Quick_Start.html">快速开始</a>）。由于原始项目已停止维护，社区也有若干改造版（EM+EE 等）可用。下载后把 <code>exe</code> 单独放进一个空文件夹即可。</p><h3 id="q-启动就报「找不到-csv-文件夹-erb-文件夹」" tabindex="-1">Q：启动就报「找不到 csv 文件夹 / erb 文件夹」？ <a class="header-anchor" href="#q-启动就报「找不到-csv-文件夹-erb-文件夹」" aria-label="Permalink to “Q：启动就报「找不到 csv 文件夹 / erb 文件夹」？”">​</a></h3><p>A：在 <code>exe</code> 同目录下手动新建 <code>CSV</code> 和 <code>ERB</code> 两个文件夹（大小写不敏感，但建议照写）。详见<a href="./Quick_Start.html">快速开始</a>。</p><h3 id="q-点了「从头开始」报-関数-eventfirst-が見つかりません" tabindex="-1">Q：点了「从头开始」报 <code>関数&quot;@EVENTFIRST&quot;が見つかりません</code>？ <a class="header-anchor" href="#q-点了「从头开始」报-関数-eventfirst-が見つかりません" aria-label="Permalink to “Q：点了「从头开始」报 関数&quot;@EVENTFIRST&quot;が見つかりません？”">​</a></h3><p>A：<code>ERB/</code> 里还没有定义 <code>@EVENTFIRST</code> 函数。新建一个 <code>System.erb</code> 并写下：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EVENTFIRST</span></span>
<span class="line"><span style="color:#569CD6;">  QUIT</span></span></code></pre></div><h2 id="报错" tabindex="-1">报错 <a class="header-anchor" href="#报错" aria-label="Permalink to “报错”">​</a></h2><h3 id="q-怎么读懂报错信息" tabindex="-1">Q：怎么读懂报错信息？ <a class="header-anchor" href="#q-怎么读懂报错信息" aria-label="Permalink to “Q：怎么读懂报错信息？”">​</a></h3><p>A：报错一般会告诉你<strong>在哪出错</strong>和<strong>出了什么错</strong>。看不懂时，打开根目录下的 <code>emuera.log</code>，里面有更详细的记录。常见错误的含义见<a href="./../reference/Error_Index.html">错误索引表</a>，排错方法见<a href="./tutorials/Error.html">错误与异常</a>。</p><h3 id="q-报-ifに対応するendifが設定されていない" tabindex="-1">Q：报 <code>IFに対応するENDIFが設定されていない</code>？ <a class="header-anchor" href="#q-报-ifに対応するendifが設定されていない" aria-label="Permalink to “Q：报 IFに対応するENDIFが設定されていない？”">​</a></h3><p>A：复合语句必须成对闭合。检查 <code>IF</code>…<code>ENDIF</code>、<code>REPEAT</code>…<code>REND</code>、<code>FOR</code>…<code>NEXT</code> 是否配对，用编辑器的折叠功能最容易发现。</p><h3 id="q-报-の前後で型が一致しません" tabindex="-1">Q：报 <code>&#39;=&#39;の前後で型が一致しません</code>？ <a class="header-anchor" href="#q-报-の前後で型が一致しません" aria-label="Permalink to “Q：报 &#39;=&#39;の前後で型が一致しません？”">​</a></h3><p>A：赋值号两边类型不同。字符串变量要用 <code>#DIMS</code> 定义，值要加双引号；数值变量不能装文本。</p><h3 id="q-报-配列の範囲外です" tabindex="-1">Q：报 <code>配列の範囲外です</code>？ <a class="header-anchor" href="#q-报-配列の範囲外です" aria-label="Permalink to “Q：报 配列の範囲外です？”">​</a></h3><p>A：数组下标从 0 开始，访问了不存在的元素。检查下标是否越界或为负。</p><h2 id="脚本" tabindex="-1">脚本 <a class="header-anchor" href="#脚本" aria-label="Permalink to “脚本”">​</a></h2><h3 id="q-print-和-prints-有什么区别" tabindex="-1">Q：<code>Print</code> 和 <code>PrintS</code> 有什么区别？ <a class="header-anchor" href="#q-print-和-prints-有什么区别" aria-label="Permalink to “Q：Print 和 PrintS 有什么区别？”">​</a></h3><p>A：<code>Print</code> 打印后面的<strong>字面文本</strong>，<code>PrintS</code> 打印<strong>字符串变量里的值</strong>。还有 <code>PrintV</code> 用于数值变量。详见<a href="./tutorials/Type.html">数值与文本</a>。</p><h3 id="q-为什么-5-3-等于-1-而不是-1-66" tabindex="-1">Q：为什么 <code>5/3</code> 等于 1 而不是 1.66？ <a class="header-anchor" href="#q-为什么-5-3-等于-1-而不是-1-66" aria-label="Permalink to “Q：为什么 5/3 等于 1 而不是 1.66？”">​</a></h3><p>A：EraBasic 的数值是整数，<code>/</code> 是整除。想保留小数，通常用「先乘 100 再除」的办法。</p><h3 id="q-函数怎么传参数、怎么返回值" tabindex="-1">Q：函数怎么传参数、怎么返回值？ <a class="header-anchor" href="#q-函数怎么传参数、怎么返回值" aria-label="Permalink to “Q：函数怎么传参数、怎么返回值？”">​</a></h3><p>A：参数用 <code>ARG</code>（数值）/ <code>ARGS</code>（字符串），返回值放在 <code>RESULT</code> 里。详见<a href="./tutorials/Function.html">函数的定义与用法</a>。</p><h3 id="q-事件函数是什么-为什么引擎会自己调用它们" tabindex="-1">Q：事件函数是什么？为什么引擎会自己调用它们？ <a class="header-anchor" href="#q-事件函数是什么-为什么引擎会自己调用它们" aria-label="Permalink to “Q：事件函数是什么？为什么引擎会自己调用它们？”">​</a></h3><p>A：<code>@EVENTFIRST</code>、<code>@SHOW_SHOP</code> 等是引擎在固定时机自动调用的「框架函数」。完整清单见<a href="./tutorials/System_Flow.html">内置流程</a>。</p><h2 id="存档" tabindex="-1">存档 <a class="header-anchor" href="#存档" aria-label="Permalink to “存档”">​</a></h2><h3 id="q-savedata-和-savegame-有什么区别" tabindex="-1">Q：<code>SAVEDATA</code> 和 <code>SAVEGAME</code> 有什么区别？ <a class="header-anchor" href="#q-savedata-和-savegame-有什么区别" aria-label="Permalink to “Q：SAVEDATA 和 SAVEGAME 有什么区别？”">​</a></h3><p>A：<code>SAVEDATA</code> 直接存到指定编号的槽位，可以在脚本任何位置调用；<code>SAVEGAME</code> 呼出引擎自带存档界面，只能在 <code>SHOP</code> 流程中调用。详见<a href="./tutorials/Save_Load.html">游戏的保存与加载</a>。</p><h3 id="q-读档前为什么要先-chkdata" tabindex="-1">Q：读档前为什么要先 <code>CHKDATA</code>？ <a class="header-anchor" href="#q-读档前为什么要先-chkdata" aria-label="Permalink to “Q：读档前为什么要先 CHKDATA？”">​</a></h3><p>A：<code>LOADDATA</code> 读取失败会直接报错。先用 <code>CHKDATA</code> 检查，<code>RESULT</code> 为 0 时才读取。</p><h3 id="q-存档是乱码-换台电脑读不了" tabindex="-1">Q：存档是乱码 / 换台电脑读不了？ <a class="header-anchor" href="#q-存档是乱码-换台电脑读不了" aria-label="Permalink to “Q：存档是乱码 / 换台电脑读不了？”">​</a></h3><p>A：存档默认使用 Shift-JIS 编码。可以在配置中改为 UTF-8 或二进制格式保存，但这会影响与旧版 Eramaker/Emuera 的兼容性。详见<a href="./../translation/Config_Settings.html">配置项详解</a>。</p><h2 id="兼容性" tabindex="-1">兼容性 <a class="header-anchor" href="#兼容性" aria-label="Permalink to “兼容性”">​</a></h2><h3 id="q-同一个脚本在不同引擎里表现不一样" tabindex="-1">Q：同一个脚本在不同引擎里表现不一样？ <a class="header-anchor" href="#q-同一个脚本在不同引擎里表现不一样" aria-label="Permalink to “Q：同一个脚本在不同引擎里表现不一样？”">​</a></h3><p>A：不同引擎/改造版支持的特性不同。Emuera 与 Eramaker 的差异见<a href="./../translation/Difference.html">与 Eramaker 的差异</a>；配置里还有一组「兼容性开关」可以让 Emuera 模仿旧行为。</p><h3 id="q-升级-emuera-后脚本报错-显示错乱怎么办" tabindex="-1">Q：升级 Emuera 后脚本报错 / 显示错乱怎么办？ <a class="header-anchor" href="#q-升级-emuera-后脚本报错-显示错乱怎么办" aria-label="Permalink to “Q：升级 Emuera 后脚本报错 / 显示错乱怎么办？”">​</a></h3><p>A：多与兼容性开关有关。例如显示错乱可以尝试<code>ver1739以前の非ボタン折り返しを再現する</code>，函数参数报错可以尝试<code>ユーザー関数の引数に自動的にTOSTRを補完する</code>。逐项说明见<a href="./../translation/Config_Settings.html#兼容性">配置项详解</a>。</p><h2 id="性能" tabindex="-1">性能 <a class="header-anchor" href="#性能" aria-label="Permalink to “性能”">​</a></h2><h3 id="q-游戏很卡怎么办" tabindex="-1">Q：游戏很卡怎么办？ <a class="header-anchor" href="#q-游戏很卡怎么办" aria-label="Permalink to “Q：游戏很卡怎么办？”">​</a></h3><p>A：常见瓶颈在循环。能一次算完的不要每次输入都重算；批量赋值用 <code>VARSET</code> 等内置指令，比手写 <code>FOR</code> 循环快得多。详见<a href="./advanced/Experience.html">开发实战经验与技巧</a>。</p><h3 id="q-脚本陷入死循环了" tabindex="-1">Q：脚本陷入死循环了？ <a class="header-anchor" href="#q-脚本陷入死循环了" aria-label="Permalink to “Q：脚本陷入死循环了？”">​</a></h3><p>A：Emuera 会在超过「无限循环警告的毫秒数」且期间没有执行 <code>WAIT</code> 时弹出警告。把该值与 <code>WAIT</code> 配合使用即可。</p><h2 id="发布" tabindex="-1">发布 <a class="header-anchor" href="#发布" aria-label="Permalink to “发布”">​</a></h2><h3 id="q-怎么把游戏交给别人玩" tabindex="-1">Q：怎么把游戏交给别人玩？ <a class="header-anchor" href="#q-怎么把游戏交给别人玩" aria-label="Permalink to “Q：怎么把游戏交给别人玩？”">​</a></h3><p>A：把 <code>exe</code>、<code>CSV/</code>、<code>ERB/</code>（以及 <code>resources/</code> 等资源）一起打包即可。注意<strong>不要</strong>把 <code>emuera.config</code> 里的个人设置强加给玩家，除非确有需要（此时用 <code>_fixed.config</code>）。同时确认目标玩家使用的引擎版本支持你用到的特性。</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to “相关链接”">​</a></h2><ul><li><a href="./Quick_Start.html">快速开始</a></li><li><a href="./tutorials/">入门教程</a></li><li><a href="./../reference/">参考</a></li><li><a href="./../reference/Error_Index.html">错误索引表</a></li></ul>`,50)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};